// We use the Verus verification framework to implement and verify a simple
// primality test for n ≥ 2.
//
// The function prime_num returns true if and only if there is no integer
// k in the range [2, n) that divides n exactly. We prove this fact
// by maintaining an invariant in the loop that no divisor has been found
// so far, and we decrease the variant `n - i` on each iteration to ensure
// termination.

verus! {
    /// Returns true iff `n` is prime, i.e., there is no `k` with 2 ≤ k < n
    /// that divides `n` exactly.
    fn prime_num(n: u64) -> bool
        requires
            // We only handle inputs ≥ 2
            n >= 2,
        ensures
            // The result matches the mathematical definition of primality
            result == (forall |k: u64| 2 <= k && k < n ==> n % k != 0)
    {
        // We search for a divisor in [2, n). If we find one, we return false.
        let mut i: u64 = 2;

        // Loop invariant: no divisor has been found in [2, i).
        // Bound invariant: 2 ≤ i ≤ n.
        //
        // We also provide a decreases clause `n - i` so that Verus can verify
        // this loop terminates: each iteration increases `i` by 1, so
        // `n - i` strictly decreases.
        while i < n
            invariant 2 <= i && i <= n
            invariant forall |k: u64| 2 <= k && k < i ==> n % k != 0
            decreases n - i
        {
            if n % i == 0 {
                // We found a proper divisor, so n is composite.
                return false;
            }
            // Otherwise, advance to the next candidate.
            i = i + 1;
        }

        // If the loop completes without finding any divisor, n is prime.
        true
    }
}